            for (String s : inputArray) {
                arr.add(Integer.parseInt(s));
            }

            Solution obj = new Solution();
            int[] arrInt = arr.stream().mapToInt(i -> i).toArray();
            int ans = obj.countSubarray(arrInt, l, r);

            System.out.println(ans);
            System.out.println("~");
        }

        scanner.close();
    }
}

